using System;
using NUnit.Framework;
using LWS.TruckFashionShow;
using LWS.TruckDanceOff;
public sealed class FashionRulesTests
{
    static FashionItem Item(string id,string slot)=>new FashionItem(id,slot,FashionRules.Tags(id));
    [Test]public void RealCrownAndGoldItemsEarnTransparentRoyalThemePointsWhileUnknownItemsCannot(){var royal=FashionRules.Judge(FashionTheme.Royalty,new[]{Item("hat.crown","hat"),Item("mirrors.gold","mirrors"),Item("wheels.gold","wheels")},0,12,0,12000,false);Assert.That(royal.theme,Is.EqualTo(120));Assert.That(royal.coordination,Is.EqualTo(60));var unknown=FashionRules.Judge(FashionTheme.Royalty,new[]{Item("unreleased.magic.crown","hat")},0,12,0,12000,false);Assert.That(unknown.theme,Is.Zero);Assert.That(FashionRules.Tags("unreleased.magic.crown"),Is.EqualTo(FashionTag.None));}
    [Test]public void CoordinationRequiresActualMatchingFinishesAndCreativityUsesRealSlots(){var a=FashionRules.Judge(FashionTheme.FancyEvening,new[]{Item("mirrors.chrome","mirrors"),Item("wheels.chrome","wheels")},0,12,0,12000,false);var b=FashionRules.Judge(FashionTheme.FancyEvening,new[]{Item("mirrors.gold","mirrors"),Item("wheels.chrome","wheels")},0,12,0,12000,false);Assert.That(a.coordination,Is.GreaterThan(b.coordination));Assert.That(a.creativity,Is.EqualTo(16));Assert.Throws<ArgumentException>(()=>FashionRules.Judge(FashionTheme.FancyEvening,new[]{Item("hat.crown","hat"),Item("hat.party","hat")},0,12,0,12000,false));}
    [Test]public void OriginalDanceRulesResolveForgivingInputsAndEmptyPressPenaltyWithoutAnimationAuthority(){var timing=new DanceRules(new[]{new DanceNote(1,1),new DanceNote(2,4,.3)},.12,.28);timing.Step(1.2,1,1);Assert.That(timing.Good,Is.EqualTo(1));timing.Step(1.5,2,2);Assert.That(timing.EmptyPresses,Is.EqualTo(1));timing.Step(2,4,4);timing.Step(2.3,0,4);Assert.That(timing.Resolved,Is.EqualTo(2));Assert.That(timing.Perfect,Is.EqualTo(1));Assert.That(timing.Score,Is.EqualTo(1410));timing.Step(3,0,0);Assert.That(timing.Resolved,Is.EqualTo(2));}
    [Test]public void CompletionRequiresActualFinalMarkAndPerformanceIsNotRandom(){var items=new[]{Item("hat.party","hat"),Item("mouth.goofy","face.mouth")};var first=FashionRules.Judge(FashionTheme.WildlyRidiculous,items,8,12,7000,12000,false);var second=FashionRules.Judge(FashionTheme.WildlyRidiculous,items,8,12,7000,12000,true);Assert.That(second.Total-first.Total,Is.EqualTo(100));Assert.That(second.Total,Is.EqualTo(FashionRules.Judge(FashionTheme.WildlyRidiculous,items,8,12,7000,12000,true).Total));var failed=FashionRules.Judge(FashionTheme.WildlyRidiculous,items,0,12,0,12000,true);Assert.That(second.qte,Is.GreaterThan(failed.qte));Assert.That(failed.poses,Is.Zero);}
    [Test]public void OrderedTurnLocksOnceOnlyAndRejectsForgedNegativeGrade(){var show=new FashionCompetition(4);var grade=new FashionGrade(40,30,24,500,200,100);Assert.That(show.Lock(1,grade),Is.False);Assert.That(show.Lock(0,new FashionGrade(-1,0,0,0,0,0)),Is.False);for(int i=0;i<4;i++){Assert.That(show.Lock(i,grade),Is.True);Assert.That(show.Lock(i,grade),Is.False);}Assert.That(show.Complete,Is.True);Assert.That(show.Leaders(),Has.Length.EqualTo(4));Assert.That(show.Scores,Is.All.EqualTo(grade.Total));}
    [Test]public void InvalidTimingOrUnknownThemeCannotProduceAResult(){Assert.Throws<ArgumentException>(()=>FashionRules.Judge((FashionTheme)9,Array.Empty<FashionItem>(),0,12,0,12000,true));Assert.Throws<ArgumentException>(()=>FashionRules.Judge(FashionTheme.Royalty,Array.Empty<FashionItem>(),13,12,0,12000,true));}
}
